CREATE TABLE public.phone_owner_roles (user_id uuid PRIMARY KEY, role text NOT NULL DEFAULT 'owner');
GRANT SELECT ON public.phone_owner_roles TO authenticated;
GRANT ALL ON public.phone_owner_roles TO service_role;
ALTER TABLE public.phone_owner_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_role_read ON public.phone_owner_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_phone_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.phone_owner_roles WHERE user_id = auth.uid() AND role = 'owner') $$;
REVOKE ALL ON FUNCTION public.is_phone_owner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_phone_owner() TO anon, authenticated, service_role;
CREATE FUNCTION public.assign_phone_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'hanzhiyun306@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.phone_owner_roles(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_phone_owner() FROM PUBLIC;
CREATE TRIGGER assign_phone_owner AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_phone_owner();
CREATE TABLE public.phone_shared_content (id text PRIMARY KEY DEFAULT 'main', payload jsonb NOT NULL DEFAULT '{}'::jsonb, revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.phone_shared_content TO anon, authenticated;
GRANT INSERT, UPDATE ON public.phone_shared_content TO authenticated;
GRANT ALL ON public.phone_shared_content TO service_role;
ALTER TABLE public.phone_shared_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY shared_phone_read ON public.phone_shared_content FOR SELECT TO anon, authenticated USING (id = 'main');
CREATE POLICY shared_phone_insert ON public.phone_shared_content FOR INSERT TO authenticated WITH CHECK (id = 'main' AND public.is_phone_owner());
CREATE POLICY shared_phone_update ON public.phone_shared_content FOR UPDATE TO authenticated USING (id = 'main' AND public.is_phone_owner()) WITH CHECK (id = 'main' AND public.is_phone_owner());
CREATE FUNCTION public.save_phone_content(p_patch jsonb, p_revision bigint) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE result bigint; BEGIN IF NOT public.is_phone_owner() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_revision = 0 THEN INSERT INTO public.phone_shared_content(id, payload, revision) VALUES('main', p_patch, 1) ON CONFLICT DO NOTHING RETURNING revision INTO result; ELSE UPDATE public.phone_shared_content SET payload = payload || p_patch, revision = revision + 1, updated_at = now() WHERE id = 'main' AND revision = p_revision RETURNING revision INTO result; END IF; IF result IS NULL THEN RAISE EXCEPTION 'Content changed on another device. Reload before saving.'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_phone_content(jsonb,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_phone_content(jsonb,bigint) TO authenticated;
CREATE POLICY shared_media_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'phone-shared-media' AND public.is_phone_owner());
CREATE POLICY shared_media_read ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'phone-shared-media' AND (public.is_phone_owner() OR EXISTS (SELECT 1 FROM public.phone_shared_content WHERE id = 'main' AND strpos(payload::text, 'shared-media:' || storage.objects.name) > 0)));
